  IonSpinner,
  useIonViewWillEnter,
  IonDatetime,
  DatetimeChangeEventDetail,,
  InputInputEventDetail,
  SearchbarInputEventDetail
} from '@ionic/react';
import { add, pencil, trash, close, save, checkmarkCircle } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  FactoryRunUsage,
  getAllFactoryRunUsages,
  createFactoryRunUsage,
  updateFactoryRunUsage,
  deleteFactoryRunUsage,
} from '../api/factoryRunUsageApi';
import './FactoryRunUsagePage.css';

interface PopoverState {
  showAlertPopover: boolean;
  showMailPopover: boolean;
  event?: Event;
}

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Apply UTC-7 offset for Hermosillo
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryRunUsagePage: React.FC = () => {
  const { companyId, userId, roleCode } = useUser();

  const [factoryRunUsages, setFactoryRunUsages] = useState<FactoryRunUsage[]>([]);
  const [filteredUsages, setFilteredUsages] = useState<FactoryRunUsage[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentFactoryRunUsage, setCurrentFactoryRunUsage] = useState<FactoryRunUsage | null>(null);
  const [searchText, setSearchText] = useState('');
  const [formFields, setFormFields] = useState<Partial<FactoryRunUsage>>({});
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);

  // Popover state for Header component
  const [popoverState, setPopoverState] = useState<PopoverState>({
    showAlertPopover: false,
    showMailPopover: false,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const loadData = async () => {
    setLoading(true);
    try {
      const data = await getAllFactoryRunUsages(); // companyId not applicable for this module
      setFactoryRunUsages(data);
      setFilteredUsages(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar los usos de Factory Run');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    loadData();
  });

  useEffect(() => {
    if (searchText === '') {
      setFilteredUsages(factoryRunUsages);
    } else {
      setFilteredUsages(
        factoryRunUsages.filter(
          (usage) =>
            usage.factoryRunRef.toLowerCase().includes(searchText.toLowerCase()) ||
            usage.modelName.toLowerCase().includes(searchText.toLowerCase())
        )
      );
    }
  }, [searchText, factoryRunUsages]);

  const handleAddClick = () => {
    setIsEditing(false);
    setCurrentFactoryRunUsage(null);
    setFormFields({
      factoryRunRef: '',
      promptTokens: 0,
      completionTokens: 0,
      totalTokens: 0,
      costUSD: 0,
      modelName: '',
      timestamp: new Date().toISOString(),
    });
    setShowModal(true);
  };

  const handleEditClick = (usage: FactoryRunUsage) => {
    setIsEditing(true);
    setCurrentFactoryRunUsage(usage);
    setFormFields({
      factoryRunRef: usage.factoryRunRef,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      costUSD: usage.costUSD,
      modelName: usage.modelName,
      timestamp: usage.timestamp,
    });
    setShowModal(true);
  };

  const handleDeleteClick = (usage: FactoryRunUsage) => {
    setCurrentFactoryRunUsage(usage);
    setShowDeleteAlert(true);
  };

  const doDelete = async () => {
    if (currentFactoryRunUsage) {
      setLoading(true);
      try {
        await deleteFactoryRunUsage(currentFactoryRunUsage.factoryRunUsageId); // companyId not applicable
        loadData();
        setError('Uso de Factory Run eliminado correctamente.');
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar el uso de Factory Run.');
      } finally {
        setLoading(false);
        setShowDeleteAlert(false);
      }
    }
  };

  const handleSave = async () => {
    if (!formFields.factoryRunRef || !formFields.modelName || formFields.promptTokens === undefined || formFields.completionTokens === undefined || formFields.costUSD === undefined) {
      setError('Por favor, complete todos los campos requeridos.');
      return;
    }

    setSaving(true);
    try {
      const payload = {
        ...formFields,
        promptTokens: Number(formFields.promptTokens),
        completionTokens: Number(formFields.completionTokens),
        totalTokens: Number(formFields.totalTokens),
        costUSD: Number(formFields.costUSD),
        timestamp: formFields.timestamp ? new Date(formFields.timestamp).toISOString() : new Date().toISOString(),
      };

      if (isEditing && currentFactoryRunUsage) {
        await updateFactoryRunUsage(currentFactoryRunUsage.factoryRunUsageId, payload);
        setError('Uso de Factory Run actualizado correctamente.');
      } else {
        await createFactoryRunUsage(payload as Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at">);
        setError('Uso de Factory Run creado correctamente.');
      }
      setShowModal(false);
      loadData();
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el uso de Factory Run.');
    } finally {
      setSaving(false);
    }
  };

  const handleInfiniteScroll = (ev: CustomEvent<void>) => {
    // For this module, assuming getAllFactoryRunUsages fetches all data.
    // If backend supported pagination, logic would go here.
    // As currently implemented, all data is loaded, so this just completes the event.
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail>, field: keyof FactoryRunUsage) => {
    setFormFields(prev => ({
      ...prev,
      [field]: e.detail.value!,
    }));
  };

  const handleDatetimeChange = (e: CustomEvent<DatetimeChangeEventDetail>) => {
    setFormFields(prev => ({
      ...prev,
      timestamp: e.detail.value ? String(e.detail.value) : new Date().toISOString(),
    }));
  };

  return (
    <IonPage className="factoryrunusage-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Usos de Factory Run — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
          placeholder="Buscar por referencia o modelo"
        />

        {loading ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <p>Cargando usos de Factory Run...</p>
          </div>
        ) : (
          <IonList className="factoryrunusage-list">
            {filteredUsages.map((usage) => (
              <IonItemSliding key={usage.factoryRunUsageId}>
                <IonItem className="factoryrunusage-item">
                  <IonLabel>
                    <h2>{usage.factoryRunRef} - {usage.modelName}</h2>
                    <p className="factoryrunusage-item-details">
                      Tokens: {usage.promptTokens} (P) / {usage.completionTokens} (C) / {usage.totalTokens} (Total)
                    </p>
                    <p className="factoryrunusage-item-details">
                      Costo: ${usage.costUSD.toFixed(2)} USD
                    </p>
                    <p className="factoryrunusage-item-details">
                      Fecha: {toHermosillo(usage.timestamp)}
                    </p>
                    <p className="factoryrunusage-item-details">
                      Creado: {toHermosillo(usage.created_At)}
                    </p>
                  </IonLabel>
                </IonItem>
                <IonItemOptions side="end">
                  <IonItemOption onClick={() => handleEditClick(usage)} color="primary">
                    <IonIcon slot="icon-only" icon={pencil} />
                  </IonItemOption>
