            <IonInfiniteScroll onIonInfinite={handleInfiniteScroll}>
              <IonInfiniteScrollContent loadingText="Cargando más datos..." />
            </IonInfiniteScroll>
          </IonList>
        )}

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
