            <IonButtons slot="end">
              <IonButton onClick={handleSave} disabled={saving}>
                {saving ? <IonSpinner name="dots" /> : <IonIcon icon={save} />}
              </IonButton>
            </IonButtons>
          </IonToolbar>
          <IonContent className="ion-padding factoryrunusage-modal-content">
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Referencia Factory Run *"
                labelPlacement="floating"
                value={formFields.factoryRunRef}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'factoryRunRef')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Nombre del Modelo *"
                labelPlacement="floating"
                value={formFields.modelName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'modelName')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Tokens Prompt *"
                labelPlacement="floating"
                type="number"
                value={formFields.promptTokens}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'promptTokens')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Tokens Completion *"
                labelPlacement="floating"
                type="number"
                value={formFields.completionTokens}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'completionTokens')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Total de Tokens *"
                labelPlacement="floating"
                type="number"
                value={formFields.totalTokens}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'totalTokens')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Costo USD *"
                labelPlacement="floating"
                type="number"
                step="0.01"
                value={formFields.costUSD}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => handleInputChange(e, 'costUSD')}
              />
            </div>
            <div className="factoryrunusage-form-field">
              <IonInput
                fill="outline"
                label="Fecha y Hora *"
                labelPlacement="floating"
                value={toHermosillo(formFields.timestamp)}
